css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: A4 portrait;
  margin: 0;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  padding: 0 !important;
}

.cd-goods-receipt, .cd-goods-receipt * { box-sizing: border-box; }
.cd-goods-receipt { position: relative; width: 210mm; height: 297mm; overflow: hidden; color: #333; background: #fff; font-family: "TH Sarabun Document", sans-serif; font-size: 3.7mm; line-height: 1.05; }
.cd-goods-receipt small { display: block; font-size: 2.6mm; line-height: 1; }
.cd-goods-receipt .document-header { position: relative; height: 57mm; }
.cd-goods-receipt .company-logo { position: absolute; top: 15mm; left: 12mm; width: 22mm; height: 10mm; object-fit: contain; }
.cd-goods-receipt .company-info { position: absolute; top: 12mm; left: 37mm; width: 115mm; }
.cd-goods-receipt .company-info strong { display: block; font-size: 5.5mm; font-weight: 400; }
.cd-goods-receipt .company-info span { display: block; margin-top: 2mm; }
.cd-goods-receipt h1 { position: absolute; top: 34mm; right: 35mm; margin: 0; font-size: 6mm; font-weight: 400; }
.cd-goods-receipt h2 { position: absolute; top: 48mm; right: 35mm; margin: 0; font-size: 4.5mm; }
.cd-goods-receipt .receipt-info { display: grid; grid-template-columns: 55% 45%; width: 182mm; height: 46mm; margin: 0 14mm 1mm; }
.cd-goods-receipt .supplier-panel, .cd-goods-receipt .document-panel { position: relative; padding: 3mm 4mm; border: 0.25mm solid #333; border-radius: 2.5mm; }
.cd-goods-receipt .supplier-panel { margin-right: 1.5mm; }
.cd-goods-receipt .supplier-name { position: absolute; top: 4mm; left: 25mm; right: 3mm; font-weight: 700; }
.cd-goods-receipt .supplier-address { position: absolute; top: 10mm; left: 5mm; right: 3mm; height: 20mm; overflow: hidden; }
.cd-goods-receipt .bill, .cd-goods-receipt .remark { position: absolute; left: 4mm; right: 4mm; }
.cd-goods-receipt .bill { bottom: 9mm; } .cd-goods-receipt .remark { bottom: 2mm; }
.cd-goods-receipt .bill span, .cd-goods-receipt .remark span { display: inline-block; width: 32mm; }
.cd-goods-receipt .document-panel dl { display: grid; grid-template-columns: 35mm 1fr; grid-auto-rows: 7.5mm; margin: 0; }
.cd-goods-receipt .document-panel dt, .cd-goods-receipt .document-panel dd { margin: 0; }
.cd-goods-receipt .items-section { width: 182mm; height: 100mm; margin: 0 14mm; }
.cd-goods-receipt table { width: 100%; height: 100%; border-collapse: separate; border-spacing: 0; table-layout: fixed; border: 0.25mm solid #333; border-radius: 2.5mm 2.5mm 0 0; overflow: hidden; }
.cd-goods-receipt th, .cd-goods-receipt td { padding: 1.3mm; border-right: 0.25mm solid #333; }
.cd-goods-receipt th:last-child, .cd-goods-receipt td:last-child { border-right: 0; }
.cd-goods-receipt th { height: 10mm; border-bottom: 0.25mm solid #333; font-weight: 400; text-align: center; }
.cd-goods-receipt td { vertical-align: top; }
.cd-goods-receipt td:nth-child(1), .cd-goods-receipt td:nth-child(3) { text-align: center; }
.cd-goods-receipt td:nth-child(4), .cd-goods-receipt td:nth-child(5) { text-align: right; }
.cd-goods-receipt col.no { width: 6.5%; } .cd-goods-receipt col.description { width: 48%; } .cd-goods-receipt col.quantity { width: 17%; } .cd-goods-receipt col.rate { width: 13%; } .cd-goods-receipt col.amount { width: 15.5%; }
.cd-goods-receipt .summary-section { display: grid; grid-template-columns: 55% 45%; width: 182mm; height: 55mm; margin: 0 14mm; border: 0.25mm solid #333; border-top: 0; }
.cd-goods-receipt .remarks { padding: 5mm 3mm; border-right: 0.25mm solid #333; }
.cd-goods-receipt .totals { display: grid; grid-template-columns: 55mm 1fr; grid-template-rows: repeat(6, 7.2mm) 12mm; margin: 0; }
.cd-goods-receipt .totals dt, .cd-goods-receipt .totals dd { position: relative; margin: 0; padding: 1mm 2mm; }
.cd-goods-receipt .totals dd { border-left: 0.25mm solid #333; text-align: right; }
.cd-goods-receipt .totals dt span { position: absolute; right: 1mm; bottom: 1mm; }
.cd-goods-receipt .totals .grand { border-top: 0.25mm solid #333; font-size: 4.2mm; font-weight: 700; text-align: center; }
.cd-goods-receipt .approval-section { display: grid; grid-template-columns: 1fr 1fr; width: 182mm; height: 36mm; margin: 0 14mm; padding-top: 17mm; border: 0.25mm solid #333; border-top: 0; border-radius: 0 0 2.5mm 2.5mm; text-align: center; }
.cd-goods-receipt .approval-section span { display: block; width: 45mm; margin: 0 auto 2mm; border-bottom: 0.2mm solid #555; }
